/* Ironlog — the exercise screens: the movement page (history, PRs, demo,
   notes), the equipment / grip / arm picker, the set-role and modifier pickers,
   pain and fatigue notes, the PR-pool notice and Check exercise data. Split out
   of exercises.js (ROADMAP E17 phase 3) so the library and leaf model there sit
   below the features, and these screens sit with them. */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { $, APP_VERSION, U, dw, esc, fmtDate, nice, relDay, rpeToRir, toKg, w, wt } from './core.js';
import { save } from './database.js';
import { ATT_ICON_FALLBACK, ATT_TITLE, EQ_ICON, EQ_TITLE, EXEC_ICON, EXEC_LABEL, SET_ROLES, _mvTab, attachmentsFor,
  catalogue, demoBlock, demoDesc, demoMount, exFull, exKey, exName, exTag, exVariant, feelBlock, feelSuffix,
  holdLabel, isDrop, isTimed, isWarm, isWorking, keyEntry, keyLeaf, keyNameHtml, keyVariantLabel, leafKey, leafName,
  loadConventionFor, modLabel, modVocab, modWords, movementById, prText, roleSuffix, setListLabel, setMvTab,
  setNumber, setText, variantLabel, withAxis } from './exercises.js';
import { SERIES_COLORS, chartMulti, closeAllModals, closeModal, modal, modalStack, render, toast, whatsNewArmed,
  whatsNewBusy, why } from './kit.js';
import { kitHas, placeName, roundLoadFor } from './loading.js';
import { S } from './state.js';
import { bust, movementVariants, primaryVariantKey, prsFor, statsFor } from './stats.js';
import { TEMPO_PRESETS, TEMPO_WORDS, adoptTempo, imbalanceBlock, parseTempo, prPoolMoves, shapeKind, tempoFromText,
  tempoParts } from './training.js';
import { openPRShare, viewCompleted } from './workout.js';
/* end imports */

/* ---------------- exercise screens ---------------- */
/* Equipment / execution / attachment picker. Invalid options are greyed, never
   hidden — the constraint should be visible (spec 1a). Equipment the movement
   doesn't list stays pickable (B9): a kettlebell bench is the lifter's call,
   and it becomes a leaf of its own. Execution and attachment stay locked. */
export function openAxisPicker(ei, axis) {
  const a = S.active;
  const e = a && a.exercises[ei];
  if (!e) return;
  const m = movementById(e.leaf.movement);
  if (!m) return toast('This movement is not in the catalogue');
  const V = catalogue().V;
  let tab = axis || 'equipment';

  const tabsFor = () => {
    const t = [['equipment', 'Equipment'], ['execution', 'Execution']];
    if (attachmentsFor(m, e.leaf.equipment).length > 1) t.push(['attachment', 'Attachment']);
    return t;
  };
  const optionsFor = ax => {
    if (ax === 'equipment') return (V.equipment || []).map(v => ({ v, label: (EQ_TITLE[v] || v) + (!kitHas(v) ? ` · not at ${placeName()}` : ''), icon: EQ_ICON[v], ok: (m.equipment || []).includes(v), pick: true }));
    if (ax === 'execution') return (V.execution || []).map(v => ({ v, label: EXEC_LABEL[v] || v, icon: EXEC_ICON[v], ok: (m.execution || []).includes(v) }));
    const allowed = attachmentsFor(m, e.leaf.equipment);
    return (V.attachment || []).map(v => ({ v, label: ATT_TITLE[v] || v, icon: ATT_ICON_FALLBACK, ok: allowed.includes(v) || v === 'none' }));
  };
  const draw = () => `
    <div class="seg" id="axTabs" style="margin-bottom:12px">
      ${tabsFor().map(([k, lbl]) => `<button data-axtab="${k}" class="${k === tab ? 'on' : ''}">${lbl}</button>`).join('')}
    </div>
    <div id="axList">${optionsFor(tab).sort((x, y) => (y.ok ? 1 : 0) - (x.ok ? 1 : 0)).map((o, i, all) => `
      ${!o.ok && o.pick && (i === 0 || all[i - 1].ok) ? `<div class="eyebrow" style="margin:10px 0 4px">Unusual for ${esc(m.name)}</div>` : ''}
      <button class="axrow ${o.v === e.leaf[tab] ? 'on' : ''} ${o.ok ? '' : o.pick ? 'odd' : 'off'}" ${o.ok || o.pick ? `data-axpick="${esc(o.v)}"` : 'disabled'}>
        ${o.icon || ''}<span class="lbl">${esc(o.label)}</span><span class="rad"></span>
      </button>`).join('')}</div>
    <div class="sub" style="margin-top:10px">${tab === 'equipment'
      ? `Greyed equipment isn't usual for ${esc(m.name)} — pick it anyway and it gets its own PRs.`
      : `Greyed options aren't valid for ${esc(m.name)}.`}</div>`;

  modal({
    title: exFull(e),
    body: draw(),
    foot: `<button class="btn primary wide" data-close>Done</button>`,
    onOpen: bg => {
      const bind = () => {
        bg.querySelectorAll('[data-axtab]').forEach(b => b.onclick = () => { tab = b.dataset.axtab; redraw(); });
        bg.querySelectorAll('[data-axpick]').forEach(b => b.onclick = () => {
          const before = leafKey(e.leaf);
          e.leaf = withAxis(e.leaf, tab, b.dataset.axpick);
          if (leafKey(e.leaf) !== before) {
            /* The leaf is the PR pool, so changing it moves this exercise's
               history. Say so rather than letting a number quietly change. */
            const odd = tab === 'equipment' && !(m.equipment || []).includes(e.leaf.equipment);
            toast(`${exFull(e)} · ${loadConventionFor(e.leaf) === 'per_side' ? 'per side' : 'total'} load${odd ? ' · unusual combo' : ''}`, 'green');
          }
          save(); bust(); redraw(); render();
        });
      };
      const redraw = () => { const b = $('.modal-body', bg); if (b) { b.innerHTML = draw(); bind(); } };
      bind();
    },
  });
}
/* Pick a set's role; a drop set can also be added straight after this one at
   about 80% of its weight. `sets` is the entry's list, live or in the edit
   sheet; `after` re-renders. */
export function openRolePicker(e, si, after, done) {
  const s = e.sets[si];
  if (!s) return;
  modal({
    title: `Set ${setNumber(e.sets, si)}`,
    body: `<div class="rolelist">${SET_ROLES.map(([id, label, , sub]) => `
        <button class="btn wide ghost roleopt ${(s.setType || 'working') === id ? 'on' : ''}" data-role="${id}"
          ${id === 'drop' && si === 0 ? 'disabled' : ''}>
          <span>${label}</span><span class="sub">${id === 'drop' && si === 0 ? 'Needs a set above it' : sub}</span></button>`).join('')}</div>
      ${isWarm(s) ? '' : `<button class="btn wide" id="roleAddDrop" style="margin-top:6px">+ Add a drop set after this</button>`}
      ${feelBlock(s, 'set')}`,
    foot: `<button class="btn ghost" data-close>Close</button>`,
    onClose: () => after(),
    onOpen: bg => {
      wireFeel(bg, s, 'set');
      bg.querySelectorAll('[data-role]').forEach(b => b.onclick = () => {
        s.setType = b.dataset.role;
        if (s.setType === 'amrap' && !s.done) s.r = s.r || 0;
        closeModal(); after();
      });
      const add = $('#roleAddDrop', bg);
      if (add) add.onclick = () => {
        // after the end of this set's chain, a step lighter than the last link
        let at = si; while (e.sets[at + 1] && isDrop(e.sets[at + 1])) at++;
        const last = e.sets[at];
        const w = last.w > 0 ? roundLoadFor(last.w * 0.8, e.leaf) : 0;
        e.sets.splice(at + 1, 0, { w, r: 0, rpe: null, done: !!done, setType: 'drop' });
        closeModal(); after();
      };
    },
  });
}
export function openFeel(obj, title, after) {
  modal({
    title,
    body: `<div class="sub" style="margin-top:0">A note for you and anyone you share your log with. It never changes a PR or the plan.</div>${feelBlock(obj, 'ses')}`,
    foot: `<button class="btn primary wide" data-close>Done</button>`,
    onOpen: bg => wireFeel(bg, obj, 'ses'),
    onClose: after,
  });
}
function wireFeel(bg, obj, prefix) {
  const clean = () => { const f = obj.feel; if (f && !f.pain && !f.fatigue && !f.note) delete obj.feel; };
  bg.querySelectorAll(`[data-feel^="${prefix}."]`).forEach(b => b.onclick = () => {
    const k = b.dataset.feel.split('.')[1];
    obj.feel = obj.feel || {};
    obj.feel[k] = !obj.feel[k];
    if (!obj.feel[k]) delete obj.feel[k];
    b.classList.toggle('primary', !!obj.feel[k]); b.classList.toggle('ghost', !obj.feel[k]);
    b.setAttribute('aria-pressed', obj.feel[k] ? 'true' : 'false');
    clean(); save();
  });
  const n = bg.querySelector(`[data-feelnote="${prefix}"]`);
  if (n) n.oninput = () => { obj.feel = obj.feel || {}; const v = n.value.trim(); if (v) obj.feel.note = v; else delete obj.feel.note; clean(); save(); };
}
/* Your notes: one per movement, all variants share it. Saved as you type
   (save() coalesces); clearing it deletes the key so the delete syncs. */
function demoNotesBind(bg, m) {
  const ta = $('#dmNote', bg);
  if (!ta) return;
  ta.oninput = () => {
    S.exNotes = S.exNotes || {};
    const text = ta.value.trim();
    if (text) S.exNotes[m.id] = { text: ta.value, mt: Date.now() };
    else delete S.exNotes[m.id];
    save();
  };
}
export function openModPicker(e, after) {
  adoptTempo(e);
  let sel = new Set(e.mods || []);
  let tp = e.tempo ? tempoParts(e.tempo) : ['', '', '', ''];
  let chainD = e.chainKg > 0 ? nice(dw(e.chainKg)) : '', bandD = e.bandKg > 0 ? nice(dw(e.bandKg)) : '';
  const draw = () => {
    const vocab = modVocab();
    const custom = [...sel].filter(m => String(m).startsWith('x:'));
    const cur = parseTempo(tp.map(x => x || '0').join('-'));
    return `<div class="sub" style="margin-bottom:10px">Tags on this exercise for this session. Only the ones under <b>Own PR line</b> change which PR it counts toward.</div>
      <div class="eyebrow" style="margin:4px 0 4px">Tempo</div>
      <div class="sub" style="margin-bottom:6px">Seconds down · pause at the bottom · up · pause at the top. X = as fast as you can.</div>
      <div class="row" style="gap:8px;margin-bottom:8px" id="mdTempo">
        ${TEMPO_WORDS.map((w, i) => `<div class="field" style="flex:1;margin:0"><label for="mdT${i}">${w[0].toUpperCase() + w.slice(1)}</label>
          <input id="mdT${i}" data-tp="${i}" class="mono" maxlength="1" autocapitalize="characters" autocomplete="off" value="${esc(tp[i])}" placeholder="–" style="text-align:center;font-weight:800"></div>`).join('')}
      </div>
      <div class="row wrap" style="gap:6px;margin-bottom:6px">
        ${TEMPO_PRESETS.map(pr => `<button class="btn xs mono ${cur === pr ? 'primary' : 'ghost'}" data-tpset="${pr}">${pr}</button>`).join('')}
        <button class="btn xs ghost" data-tpset="">No tempo</button>
      </div>
      <div id="mdList">
      <div class="eyebrow" style="margin:4px 0 4px">Technique</div>
      ${vocab.filter(m => !m.splitsPR && m.group !== 'adaptation').map(m => `
        <button class="axrow ${sel.has(m.id) ? 'on' : ''}" data-md="${esc(m.id)}"><span class="lbl">${esc(m.label)}</span><span class="rad"></span></button>`).join('')}
      <div class="eyebrow" style="margin:12px 0 2px">Adaptations</div>
      <div class="sub" style="margin-bottom:4px">How this lift was set up for you. Same PRs, recorded honestly. A first list — tell us what's missing.</div>
      ${vocab.filter(m => m.group === 'adaptation').map(m => `
        <button class="axrow ${sel.has(m.id) ? 'on' : ''}" data-md="${esc(m.id)}"><span class="lbl">${esc(m.label)}</span><span class="rad"></span></button>`).join('')}
      <div class="eyebrow" style="margin:12px 0 4px">Yours and others</div>
      ${custom.map(m => `
        <button class="axrow on" data-md="${esc(m)}"><span class="lbl">${esc(modLabel(m))} <span class="dimmer">yours</span></span><span class="rad"></span></button>`).join('')}
      <div class="eyebrow" style="margin:12px 0 2px">Own PR line</div>
      <div class="sub" style="margin-bottom:4px">These change the lift, so they get PRs of their own instead of counting toward the raw lift.</div>
      ${vocab.filter(m => m.splitsPR).map(m => `
        <button class="axrow ${sel.has(m.id) ? 'on' : ''}" data-md="${esc(m.id)}"><span class="lbl">${esc(m.label)}</span><span class="rad"></span></button>
        ${m.id === 'chains' && sel.has('chains') ? `<div class="field" style="margin:4px 0 8px"><label for="mdChain">Chain weight, both sides (${U()}) — optional</label>
          <input id="mdChain" type="number" inputmode="decimal" step="0.5" min="0" value="${esc(chainD)}" placeholder="e.g. 20"></div>` : ''}
        ${m.id === 'bands' && sel.has('bands') ? `<div class="field" style="margin:4px 0 8px"><label for="mdBand">Band tension at the top (${U()}) — optional</label>
          <input id="mdBand" type="number" inputmode="decimal" step="0.5" min="0" value="${esc(bandD)}" placeholder="if you know it"></div>` : ''}`).join('')}</div>
      <div class="row" style="gap:8px;margin-top:10px">
        <input id="mdNew" class="grow" placeholder="Your own — e.g. close grip, 3-0-1 tempo" maxlength="40">
        <button class="btn sm" id="mdAdd">Add</button>
      </div>`;
  };
  modal({
    title: `Modifiers · ${exFull(e)}`,
    body: draw(),
    foot: `<button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="mdOk">Done</button>`,
    onOpen: bg => {
      // the chain / band fields redraw with the list, so their values are kept here
      const keepNums = () => {
        const cIn = $('#mdChain', bg), bIn = $('#mdBand', bg);
        if (cIn) chainD = cIn.value;
        if (bIn) bandD = bIn.value;
      };
      const bind = () => {
        const tpIns = [...bg.querySelectorAll('[data-tp]')];
        tpIns.forEach((inp, i) => inp.oninput = () => {
          let v = inp.value.toUpperCase().slice(-1);
          if (v && !(v === 'X' || (v >= '0' && v <= '9'))) v = '';
          inp.value = v; tp[i] = v;
          if (v && tpIns[i + 1]) tpIns[i + 1].focus();
        });
        bg.querySelectorAll('[data-tpset]').forEach(b => b.onclick = () => {
          tp = b.dataset.tpset ? tempoParts(b.dataset.tpset) : ['', '', '', ''];
          tpIns.forEach((inp, i) => { inp.value = tp[i]; });
          bg.querySelectorAll('[data-tpset]').forEach(o => { const on = !!b.dataset.tpset && o === b; o.classList.toggle('primary', on); o.classList.toggle('ghost', !on); });
        });
        bg.querySelectorAll('[data-md]').forEach(b => b.onclick = () => {
          const id = b.dataset.md;
          if (sel.has(id)) sel.delete(id); else sel.add(id);
          b.classList.toggle('on', sel.has(id));
          if (id === 'chains' || id === 'bands') { keepNums(); $('.modal-body', bg).innerHTML = draw(); bind(); }   // show or hide its weight field
        });
        const add = () => {
          const t = $('#mdNew', bg).value.trim().replace(/\s+/g, ' ');
          if (!t) return;
          // a typed name that matches the list ticks that one rather than making a twin
          const known = modVocab().find(m => m.label.toLowerCase() === t.toLowerCase());
          const typedTempo = !known && tempoFromText(t);
          if (typedTempo) tp = tempoParts(typedTempo);   // "3-0-1 tempo" typed here fills the boxes instead
          else sel.add(known ? known.id : 'x:' + t);
          keepNums();
          $('.modal-body', bg).innerHTML = draw(); bind();
        };
        $('#mdAdd', bg).onclick = add;
        $('#mdNew', bg).onkeydown = ev => { if (ev.key === 'Enter') { ev.preventDefault(); add(); } };
      };
      bind();
      $('#mdOk', bg).onclick = () => {
        // vocabulary order first, then yours in the order added
        const order = modVocab().map(m => m.id);
        const poolBefore = exKey(e);
        e.mods = [...sel].sort((a, b) => (order.indexOf(a) + 1 || 999) - (order.indexOf(b) + 1 || 999));
        const t = tp.some(Boolean) ? parseTempo(tp.map(x => x || '0').join('-')) : null;
        if (t) e.tempo = t; else delete e.tempo;
        keepNums();
        const num = v => { const n = parseFloat(v); return n > 0 ? toKg(n) : 0; };
        const ck = sel.has('chains') ? num(chainD) : 0, bk = sel.has('bands') ? num(bandD) : 0;
        if (ck) e.chainKg = ck; else delete e.chainKg;
        if (bk) e.bandKg = bk; else delete e.bandKg;
        closeModal(); after();
        if (exKey(e) !== poolBefore) toast(`${leafName(exKey(e))} · its own PR line`, 'green');
      };
    },
  });
}
/* The movement page. A parent rolls its leaves up for presentation and stores
   nothing (section 4.3); the headline is the primary variant's or nothing at
   all (4.4), never the maximum across variants. */
export function openMovementPage(movementId, focusKey) {
  const m = movementById(movementId);
  if (!m) return toast('Not in the exercise catalogue');
  const vars = movementVariants(movementId);
  let focus = focusKey && vars.some(v => v.key === focusKey) ? focusKey : (vars[0] && vars[0].key);
  setMvTab('info');

  const strip = () => `<div class="varstrip">${vars.map(v => `
    <button class="vartab ${v.key === focus ? 'on' : ''}" data-var="${esc(v.key)}">
      <span class="n">${esc(keyVariantLabel(v.key) || 'Standard')}</span>
      <span class="m">${v.stats ? `${v.stats.sessions} session${v.stats.sessions === 1 ? '' : 's'}` : 'not logged'}</span>
    </button>`).join('')}</div>`;

  const infoTab = () => {
    const leaf = keyLeaf(focus);
    const atts = attachmentsFor(m, leaf.equipment);
    const icons = (list, cur, iconMap, labelMap) => `<div class="iconrow">${list.map(v =>
      `<span class="ic ${v === cur ? 'on' : ''}" title="${esc((labelMap && labelMap[v]) || v)}">${(iconMap && iconMap[v]) || ''}</span>`).join('')}</div>`;
    const muscles = ms => (ms || []).map(x => `<span class="chip">${esc(x)}</span>`).join(' ') || '<span class="sub">—</span>';
    return `${demoBlock(m, leaf)}${demoDesc(m, leaf)}
      <div class="row wrap" style="gap:7px;margin:16px 0 12px">
        <span class="chip">${esc(m.category)}</span>
        <span class="chip">${esc(m.metric || 'reps_weight') === 'time' ? 'timed' : 'reps × weight'}</span>
        <span class="chip">${loadConventionFor(leaf) === 'per_side' ? 'per side' : 'total'} load</span>
        ${m.verified === false ? '<span class="chip">unverified</span>' : ''}
      </div>
      <div class="eyebrow">Equipment</div>
      ${icons(m.equipment || [], leaf.equipment, EQ_ICON, EQ_TITLE)}
      <div class="eyebrow" style="margin-top:12px">Execution</div>
      ${icons(m.execution || [], leaf.execution, EXEC_ICON, EXEC_LABEL)}
      ${atts.length > 1 ? `<div class="eyebrow" style="margin-top:12px">Attachment</div>
        <div class="row wrap" style="gap:6px;margin-top:6px">${atts.map(a =>
          `<span class="chip ${a === leaf.attachment ? 'accent' : ''}">${esc(ATT_TITLE[a] || a)}</span>`).join('')}</div>` : ''}
      <div class="eyebrow" style="margin-top:14px">Primary muscles</div>
      <div class="row wrap" style="gap:6px;margin-top:6px">${muscles(m.primary)}</div>
      ${(m.secondary || []).length ? `<div class="eyebrow" style="margin-top:12px">Secondary</div>
        <div class="row wrap" style="gap:6px;margin-top:6px">${muscles(m.secondary)}</div>` : ''}
      <div class="sub" style="margin-top:14px">${vars.length} variant${vars.length === 1 ? '' : 's'} known · each keeps its own records.</div>`;
  };

  const statsTab = () => {
    const pk = primaryVariantKey(movementId);
    const ps = statsFor(pk);
    /* Section 4.4 — the headline is the primary variant's, or nothing. A
       machine chest press outranking a competition bench is nonsense. */
    const headline = ps
      ? `<div class="stats grid3" style="margin-bottom:6px">
          <div class="stat"><div class="k">Best e1RM</div><div class="v">${w(ps.best.e1)}</div><div class="d">${esc(variantLabel(keyLeaf(pk)) || 'standard')}</div>${why('e1', ps.best.w, ps.best.r, ps.best.rpe)}</div>
          <div class="stat"><div class="k">Top set</div><div class="v">${w(ps.bestW.w)}</div><div class="d">× ${ps.bestW.r}</div></div>
          <div class="stat"><div class="k">Sessions</div><div class="v">${ps.sessions}</div><div class="d">${ps.totalSets} sets</div></div>
        </div>`
      : `<div class="card tight" style="margin-bottom:10px"><div class="sub">No headline figure — the primary variant
          (${esc(variantLabel(keyLeaf(pk)) || 'the standard version')}) hasn't been logged. Variants are never rolled up into one number.</div></div>`;
    const rows = vars.filter(v => v.stats).map((v, i) => `
      <tr><td><i style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${SERIES_COLORS[i % SERIES_COLORS.length]};margin-right:7px"></i>${esc(keyVariantLabel(v.key) || 'Standard')}</td>
        <td class="r mono">${w(v.stats.best.e1)}</td>
        <td class="r mono dimmer">${v.stats.sessions}s</td></tr>`).join('');
    const series = vars.filter(v => v.stats).map((v, i) => ({
      label: keyVariantLabel(v.key) || 'Standard', color: SERIES_COLORS[i % SERIES_COLORS.length],
      points: v.stats.series.map(p => ({ date: p.date, v: dw(p.e1) })),
    }));
    /* The variant picked in the strip gets its own numbers — the headline
       above stays the primary's (section 4.4). */
    const fv = vars.find(v => v.key === focus);
    const fs = fv && fv.stats;
    const focusStrip = fv && focus !== pk ? `
      <div class="eyebrow" style="margin:12px 0 6px">${esc(keyVariantLabel(fv.key) || 'Standard')}</div>
      ${fs ? `<div class="stats grid3">
          <div class="stat"><div class="k">Best e1RM</div><div class="v">${w(fs.best.e1)}</div>${why('e1', fs.best.w, fs.best.r, fs.best.rpe)}</div>
          <div class="stat"><div class="k">Top set</div><div class="v">${w(fs.bestW.w)}</div><div class="d">× ${fs.bestW.r}</div></div>
          <div class="stat"><div class="k">Last</div><div class="v" style="font-size:15px">${esc(relDay(fs.lastDate))}</div><div class="d">${fs.sessions} sessions</div></div>
        </div>` : `<div class="sub">This variant hasn't been logged yet.</div>`}` : '';
    /* Every PR this variant has had, newest first — the same records the
       calendar chips show, so reps, holds, caps and carries all appear. */
    const base = focus ? focus.split('|')[0] : null;
    const timeline = !base ? [] : S.workouts.filter(wo => wo.status === 'completed')
      .sort((a, b) => a.date < b.date ? 1 : a.date > b.date ? -1 : 0)
      .flatMap(wo => prsFor(wo).filter(p => p.key && p.key.split('|')[0] === base).map(p => ({ p, wo })));
    const tl = fv ? `
      <div class="eyebrow" style="margin:16px 0 4px">PR timeline · ${esc(keyVariantLabel(fv.key) || 'Standard')}</div>
      ${timeline.length ? `<div class="prtl">${timeline.slice(0, 30).map(({ p, wo }) => `
        <div class="prtl-row" data-hist-wo="${esc(wo.id)}">
          <span class="prtl-dot"></span>
          <div class="grow"><div class="mono"><b>${esc(prText(p))}</b>${p.label ? ` <span class="dimmer">${esc(p.what)}${p.key.includes('|') ? ` · ${esc(exTag(keyEntry(p.key)))}` : ''}</span>` : p.e1 ? ` <span class="dimmer">e1RM ${wt(p.e1)}${p.prev ? ` · ▲ ${wt(p.e1 - p.prev)}` : ''}</span>` : ''}</div>
            <div class="sub">${fmtDate(wo.date)} · ${relDay(wo.date)}</div></div>
          ${why('pr', wo.id, prsFor(wo).indexOf(p))}
          <button class="btn xs ghost" data-prtl="${esc(wo.id)}|${prsFor(wo).indexOf(p)}" aria-label="Share this PR as an image">↗</button>
        </div>`).join('')}${timeline.length > 30 ? `<div class="sub" style="padding:6px 0">…and ${timeline.length - 30} earlier</div>` : ''}</div>`
        : `<div class="sub">No PRs yet${fs ? ' — the first session sets the marks to beat' : ''}.</div>`}` : '';
    return `${headline}${focusStrip}${fv && fv.leaf && fv.leaf.execution === 'unilateral' ? imbalanceBlock(fv.key) : ''}
      <div class="eyebrow" style="margin:14px 0 6px">Estimated 1RM by variant</div>
      ${chartMulti(series, { fmt: v => nice(Math.round(v)) })}
      <div class="eyebrow" style="margin:16px 0 4px">Records per variant</div>
      <table class="vartable"><tbody>${rows || '<tr><td class="sub">Nothing logged yet</td></tr>'}</tbody></table>
      ${tl}`;
  };

  const historyTab = () => {
    const rows = [];
    S.workouts.filter(wo => wo.status === 'completed').forEach(wo => wo.exercises.forEach(e => {
      if (!e.leaf || e.leaf.movement !== movementId) return;
      const working = e.sets.filter(s => s.done && isWorking(s));
      if (!working.length) return;
      rows.push({ date: wo.date, name: exName(e), variant: [exVariant(e), exTag(e), ...modWords(e)].filter(Boolean).join(' · '),
                  key: exKey(e), leaf: e.leaf, iso: e.iso, cap: e.cap, series: e.series, seriesSec: e.seriesSec, sets: working, id: wo.id });
    }));
    rows.sort((a, b) => a.date < b.date ? 1 : -1);
    if (!rows.length) return `<div class="empty">Nothing logged yet</div>`;
    return rows.slice(0, 40).map(r => `
      <div class="card tight" style="margin-bottom:8px">
        <div class="row between" style="margin-bottom:6px">
          <div><div style="font-weight:650">${esc(r.name)}${r.variant ? ` <span class="dimmer">${esc(r.variant)}</span>` : ''}</div>
            <div class="sub">${fmtDate(r.date)} · ${relDay(r.date)}</div></div>
          <button class="btn xs ghost" data-hist-wo="${esc(r.id)}">View</button>
        </div>
        ${r.sets.map((s, i) => `<div class="exline"><span class="dimmer">${setListLabel(r.sets, i)}</span>
          <span class="mono">${shapeKind(r) ? esc(setText(r, s)) : isTimed(r) ? `${holdLabel(s)}${r.iso && s.rpe ? ` @ ${rpeToRir(s.rpe)}` : ''}` : `${s.w > 0 ? `${wt(s.w)} × ${s.r == null ? 'AMRAP' : s.r}` : `${s.r == null ? 'AMRAP' : s.r} reps`}${s.rpe ? ` @ ${rpeToRir(s.rpe)}` : ''}`}${roleSuffix(s)}${feelSuffix(s)}</span></div>`).join('')}
      </div>`).join('');
  };

  const body = () => `
    <div class="seg" id="mvTabs">
      <button data-mvtab="info" class="${_mvTab === 'info' ? 'on' : ''}">Info</button>
      <button data-mvtab="stats" class="${_mvTab === 'stats' ? 'on' : ''}">Statistics</button>
      <button data-mvtab="history" class="${_mvTab === 'history' ? 'on' : ''}">History</button>
    </div>
    ${strip()}
    <div style="margin-top:12px">${_mvTab === 'info' ? infoTab() : _mvTab === 'stats' ? statsTab() : historyTab()}</div>`;

  modal({
    title: m.name,
    body: body(),
    foot: `<button class="btn primary wide" data-close>Close</button>`,
    onOpen: bg => {
      const bind = () => {
        bg.querySelectorAll('[data-mvtab]').forEach(b => b.onclick = () => { setMvTab(b.dataset.mvtab); redraw(); });
        bg.querySelectorAll('[data-var]').forEach(b => b.onclick = () => { focus = b.dataset.var; redraw(); });
        bg.querySelectorAll('[data-hist-wo]').forEach(b => b.onclick = () => { closeAllModals(); viewCompleted(b.dataset.histWo); });
        if (_mvTab === 'info') { demoMount(bg, m, keyLeaf(focus)); demoNotesBind(bg, m); }
        bg.querySelectorAll('[data-prtl]').forEach(b => b.onclick = ev => {
          ev.stopPropagation();
          const [wid, i] = b.dataset.prtl.split('|'), wo = S.workouts.find(x => x.id === wid);
          if (wo && prsFor(wo)[+i]) openPRShare(prsFor(wo)[+i], wo);
        });
      };
      const redraw = () => { const el = $('.modal-body', bg); if (el) { el.innerHTML = body(); bind(); } };
      bind();
    },
  });
}
/* Entered from a leaf; opens that leaf's movement page focused on it. */
export function openExDetail(key) {
  const leaf = keyLeaf(key);
  if (!leaf || !leaf.movement) return;
  openMovementPage(leaf.movement, key);
}
export function maybePoolNotice() {
  if (S.settings.prPoolsNoticed || S.active || modalStack.length || whatsNewArmed || whatsNewBusy) return;
  S.settings.prPoolsNoticed = APP_VERSION; save();
  const moved = prPoolMoves(S);
  if (!moved.length) return;
  modal({
    title: 'Chains and bands have their own PRs',
    body: `<div class="sub" style="margin-top:0">Sessions tagged with chains, bands, a slingshot or equipped now count toward a PR line of their own, not the raw lift's. Nothing was deleted — these numbers just moved.</div>
      <div class="card flush" style="margin-top:10px">${moved.map(m => `<div class="ex-row" data-exdetail="${esc(m.key)}">
        <div class="grow"><div class="n">${keyNameHtml(m.key)}</div>
          <div class="m">${m.entries} session${m.entries === 1 ? '' : 's'} · best e1RM ${wt(m.best)}</div>
          <div class="m">${esc(m.rawName)}: ${wt(m.rawBefore)} → ${m.rawAfter ? wt(m.rawAfter) : 'no other sessions'}</div></div></div>`).join('')}</div>
      <div class="sub" style="margin-top:10px">Wrong tag on a session? Edit it and untick the modifier. The full list is in Settings → Check exercise data.</div>`,
    foot: `<button class="btn primary wide" data-close>Got it</button>`,
    onOpen: bg => bg.querySelectorAll('[data-exdetail]').forEach(b => b.onclick = () => { closeModal(); openExDetail(b.dataset.exdetail); }),
  });
}
